import random
import re


_DECIMAL = r"[+-]?[0-9]+"


def _bounded_decimal(token, max_digits):
    digits = token.lstrip("+-").lstrip("0")
    if len(digits) > max_digits:
        return None
    magnitude = int(digits or "0")
    return -magnitude if token.startswith("-") else magnitude


def _parse(inp):
    tokens = inp.split()
    if len(tokens) < 4:
        return None

    values = []
    for token in tokens:
        if re.fullmatch(_DECIMAL, token) is None:
            return None
        value = _bounded_decimal(token, 6)
        if value is None:
            return None
        values.append(value)

    n, m, s, t = values[:4]
    if not 2 <= n <= 200_000:
        return None
    if not n - 1 <= m <= min(n * (n - 1) // 2, 200_000):
        return None
    if len(values) != 4 + 2 * m:
        return None
    if not (1 <= s <= n and 1 <= t <= n and s != t):
        return None

    neighbors = [set() for _ in range(n + 1)]
    for index in range(4, len(values), 2):
        u, v = values[index], values[index + 1]
        if not 1 <= u < v <= n or v in neighbors[u]:
            return None
        neighbors[u].add(v)
        neighbors[v].add(u)

    colors = [-1] * (n + 1)
    colors[1] = 0
    pending = [1]
    reached = 1
    bipartite = True
    while pending:
        vertex = pending.pop()
        for neighbor in neighbors[vertex]:
            if colors[neighbor] == -1:
                colors[neighbor] = 1 - colors[vertex]
                pending.append(neighbor)
                reached += 1
            elif colors[neighbor] == colors[vertex]:
                bipartite = False
    if reached != n:
        return None
    return neighbors, n, m, s, t, bipartite


def validate_input(inp: str) -> bool:
    return _parse(inp) is not None


def _format(n, s, t, edges):
    lines = [f"{n} {len(edges)} {s} {t}"]
    lines.extend(f"{u} {v}" for u, v in edges)
    return "\n".join(lines) + "\n"


def _edge(u, v):
    return min(u, v), max(u, v)


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    fixtures = [
        (2, 1, 2, [(1, 2)]),
        (3, 1, 2, [(1, 2), (2, 3), (1, 3)]),
        (8, 3, 6, [(v, v + 1) for v in range(1, 8)]),
        (4, 1, 3, [(1, 2), (2, 3), (3, 4), (1, 4)]),
        (4, 2, 3, [(1, 2), (1, 3), (1, 4)]),
        (4, 1, 2, [(1, 2), (1, 3), (1, 4)]),
        (5, 3, 5, [(1, 2), (2, 3), (1, 5), (2, 4), (1, 3), (2, 5)]),
        (8, 1, 8, [(u, v) for u in range(1, 9) for v in range(u + 1, 9)]),
        (8, 6, 8, [(1, 2), (2, 3), (1, 3), (3, 4),
                   (4, 5), (5, 6), (6, 7), (7, 8)]),
    ]
    cases = [_format(*case) for case in fixtures[:max(0, n)]]
    while len(cases) < n:
        size = rng.randint(2, 8)
        labels = list(range(1, size + 1))
        rng.shuffle(labels)
        edges = {
            _edge(vertex, rng.choice(labels[:index]))
            for index, vertex in enumerate(labels[1:], start=1)
        }
        missing = [
            (u, v)
            for u in range(1, size + 1)
            for v in range(u + 1, size + 1)
            if (u, v) not in edges
        ]
        edges.update(rng.sample(missing, rng.randint(0, len(missing))))
        ordered_edges = sorted(edges)
        rng.shuffle(ordered_edges)
        s, t = rng.sample(labels, 2)
        cases.append(_format(size, s, t, ordered_edges))
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    size = 200_000
    edges = [(v, v + 1) for v in range(1, size)]
    s, t = (1, size) if rng.randrange(2) == 0 else (size, 1)
    path = _format(size, s, t, edges)

    edges.append((1, size))
    s = rng.randint(1, size)
    t = (s - 1 + size // 2) % size + 1
    cycle = _format(size, s, t, edges)
    return [path, cycle]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    graph = _parse(inp)
    if graph is None:
        return [("POST-1", "The input violates the graph or format constraints.")]

    tokens = out.split()
    if len(tokens) != 1 or re.fullmatch(_DECIMAL, tokens[0]) is None:
        return [("POST-2", "Expected exactly one decimal integer token.")]

    neighbors, n, m, s, t, bipartite = graph
    upper = n * (n - 1) - 1
    answer = _bounded_decimal(tokens[0], len(str(upper)))
    if answer is None or (answer != -1 and not 3 <= answer <= upper):
        return [("POST-4", f"Expected -1 or a value in the range 3 to {upper}.")]

    failures = []
    triangle_at_start = t in neighbors[s] and not neighbors[s].isdisjoint(neighbors[t])
    if triangle_at_start and answer != 3:
        failures.append(("POST-4", "A common neighbor of adjacent starts gives a three-move swap."))
    if answer == 3 and not triangle_at_start:
        failures.append(("POST-4", "Three moves require adjacent starts with a common neighbor."))
    if answer != -1:
        if bipartite and answer % 2:
            failures.append(("POST-4", "A swap on a bipartite graph takes an even number of moves."))
        if m == n - 1 and all(len(neighbors[v]) <= 2 for v in range(1, n + 1)):
            failures.append(("POST-4", "The pieces cannot pass each other on a path."))
    return failures


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for index, first in enumerate(gen_small(seed, n)):
        size, _, s, t, *endpoints = map(int, first.split())
        edges = list(zip(endpoints[::2], endpoints[1::2]))
        variant = index % 4
        if variant == 0:
            pairs.append(("POST-3", "equal", first, _format(size, t, s, edges)))
        elif variant == 1:
            labels = list(range(1, size + 1))
            rng.shuffle(labels)
            relabeled = [_edge(labels[u - 1], labels[v - 1]) for u, v in edges]
            second = _format(size, labels[s - 1], labels[t - 1], relabeled)
            pairs.append(("POST-3", "equal", first, second))
        elif variant == 2:
            second = _format(size, s, t, edges[::-1])
            pairs.append(("POST-3", "equal", first, second))
        else:
            size = rng.randint(4, 8)
            cycle = [(v, v + 1) for v in range(1, size)] + [(1, size)]
            s, t = rng.choice(cycle)
            cycle_edges = set(cycle)
            chords = [
                (u, v)
                for u in range(1, size + 1)
                for v in range(u + 1, size + 1)
                if (u, v) not in cycle_edges
            ]
            # Adjacent starts on the cycle can swap using the complementary arc.
            # The added edge preserves every previously legal move.
            first = _format(size, s, t, cycle)
            second = _format(size, s, t, cycle + [rng.choice(chords)])
            pairs.append(("POST-3", "ge", first, second))
    return pairs


def reference_small(inp: str) -> str | None:
    graph = _parse(inp)
    if graph is None:
        return None
    neighbors, n, _, s, t, _ = graph
    if n > 8:
        return None

    goal = (t, s)
    frontier = {(s, t)}
    seen = set(frontier)
    moves = 0
    while frontier:
        if goal in frontier:
            return str(moves)
        next_frontier = set()
        for a, b in frontier:
            next_frontier.update((v, b) for v in neighbors[a] if v != b)
            next_frontier.update((a, v) for v in neighbors[b] if v != a)
        next_frontier.difference_update(seen)
        seen.update(next_frontier)
        frontier = next_frontier
        moves += 1
    return "-1"
